#' Composite Check
#'
#' Checks whether a set of formative indicators relates to two or more 
#' outcomes through one weighted composite (rank-one reduced-rank regression), 
#' and how much is lost by using a unit-weighted sum, in sample and in 
#' cross-validation.
#' 
#'
#' @examples
#' \donttest{
#' psyWiz::compositeCheck(data, indicators = c('x1', 'x2', 'x3'), outcomes = c('y1', 'y2'))
#'}
#' @param data the data as a data frame
#' @param indicators a vector of strings naming the formative indicators
#' @param outcomes a vector of strings naming at least two outcome variables
#' @param folds an integer (default 10), the number of folds
#' @param repeats an integer (default 5), how many times the cross-validation
#'   is repeated
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$test} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$r2} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$weights} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$test$asDF}
#'
#' \code{as.data.frame(results$test)}
#'
#' @export
compositeCheck <- function(
    data,
    indicators,
    outcomes,
    folds = 10,
    repeats = 5) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("compositeCheck requires jmvcore to be installed (restart may be required)")

    if ( ! missing(indicators)) indicators <- jmvcore::resolveQuo(jmvcore::enquo(indicators))
    if ( ! missing(outcomes)) outcomes <- jmvcore::resolveQuo(jmvcore::enquo(outcomes))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(indicators), indicators, NULL),
            `if`( ! missing(outcomes), outcomes, NULL))


    options <- compositeCheckOptions$new(
        indicators = indicators,
        outcomes = outcomes,
        folds = folds,
        repeats = repeats)

    analysis <- compositeCheckClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

